#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/ztest.h>

/*
 * The test requires a board with a GPIO pin that can be configured as
 * both input and output. It is extracted from the `zephyr,user`
 * devicetree node.
 */
#if DT_NODE_EXISTS(DT_PATH(zephyr_user)) && \
	DT_NODE_HAS_PROP(DT_PATH(zephyr_user), user_gpios) && \
	DT_NODE_HAS_STATUS(DT_PHANDLE(DT_PATH(zephyr_user), user_gpios), okay)
static const struct gpio_dt_spec user_gpio =
	GPIO_DT_SPEC_GET(DT_PATH(zephyr_user), user_gpios);
#else
static const struct gpio_dt_spec user_gpio = { .port = NULL };
#endif

static void *gpio_get_direction_setup(void)
{
	int ret;

	if (user_gpio.port == NULL || !device_is_ready(user_gpio.port)) {
		ztest_test_skip();
	}

	ret = gpio_pin_configure_dt(&user_gpio, GPIO_INPUT);
	zassert_ok(ret, "gpio_pin_configure_dt failed");

	return NULL;
}

ZTEST(gpio_get_direction, test_gpio_get_direction)
{
	int ret;
	gpio_port_pins_t all_pins_mask;
	gpio_port_pins_t input_pins_mask;
	gpio_port_pins_t output_pins_mask;

	ret = gpio_port_get_direction(user_gpio.port, BIT(user_gpio.pin),
				      &input_pins_mask, &output_pins_mask);
	zassert_ok(ret, "gpio_port_get_direction failed");
	zassert_equal(input_pins_mask, BIT(user_gpio.pin),
		      "pin %d should be configured as input", user_gpio.pin);
	zassert_equal(output_pins_mask, 0,
		      "pin %d should not be configured as output", user_gpio.pin);

	ret = gpio_pin_configure_dt(&user_gpio, GPIO_OUTPUT);
	zassert_ok(ret, "gpio_pin_configure_dt failed");

	ret = gpio_port_get_direction(user_gpio.port, BIT(user_gpio.pin),
				      &input_pins_mask, &output_pins_mask);
	zassert_ok(ret, "gpio_port_get_direction failed");
	zassert_equal(input_pins_mask, 0,
		      "pin %d should not be configured as input", user_gpio.pin);
	zassert_equal(output_pins_mask, BIT(user_gpio.pin),
		      "pin %d should be configured as output", user_gpio.pin);

	/* Check if the function works correctly with all pins mask */
	all_pins_mask = 0xFFFFFFFF;
	ret = gpio_port_get_direction(user_gpio.port, all_pins_mask,
				      &input_pins_mask, &output_pins_mask);
	zassert_ok(ret, "gpio_port_get_direction failed");
	zassert_equal(input_pins_mask, 0,
		      "pin %d should not be configured as input", user_gpio.pin);
	zassert_equal(output_pins_mask, BIT(user_gpio.pin),
		      "pin %d should be configured as output", user_gpio.pin);
}

ZTEST_SUITE(gpio_get_direction, NULL, gpio_get_direction_setup, NULL, NULL, NULL);
